from pathlib import Path
import json,hashlib,math,html,csv
D=Path(__file__).parent;R=D.parent.parent
captures=json.loads((D/'captures.json').read_text()); C={x['key']:x for x in captures}
rows=[]
for key,size,n,pitch,head,height,drive,cb,gtin,pc,lc,lsku in [('m2x5','M2 × 5',12,.4,3.8,2,1.5,'CB2-5','4043952154625',483,497,'59600061503-100'),('m2x10','M2 × 10',8,.4,3.8,2,1.5,'CB2-10','4043952154656',421,433,'59600061506-100'),('m25x8','M2.5 × 8',3,.45,4.5,2.5,2,'CB2.5-8','4043952154700',483,497,'59600061605-100')]:
 offers=[]
 for vendor,cents,sku in [('pegnitz',pc,{'m2x5':'047622000020005','m2x10':'047622000020010','m25x8':'047622000025008'}[key]),('luchs',lc,lsku)]:
  cap=C[vendor+'-'+key];s=(D/(vendor+'-'+key+'.txt')).read_text();assert gtin in s and str(cents//100)+','+str(cents%100).zfill(2) in s
  offers.append({'supplier':vendor,'sku':sku,'gtin':gtin,'source':cap,'standard_claim':'DIN 912 / ISO 4762','material_claim':'steel class 12.9','finish':'Pegnitz title blank/schwarz but detail blank/uncoated; Luchs blank; confirm exact finish','package_pieces':100,'observed_package_price_eur':cents/100,'tax_basis':'includes displayed German 19% VAT; shipping additional; no destination tax assumption','availability':'listed deliverable, no numerical stock; Pegnitz 3–4 working days foreign differs; Luchs 1–4 days Germany with destination-not-available message also in HTML','batches':[{'robots':N,'nominal_need':N*n,'packages':math.ceil(N*n/100),'received':math.ceil(N*n/100)*100,'surplus':math.ceil(N*n/100)*100-N*n,'arithmetic_eur':math.ceil(N*n/100)*cents/100} for N in [1,100,1000]]})
 rows.append({'nominal_size':size,'per_robot_model_count':n,'identity_status':'CANNOT DETERMINE: nominal model candidate only','dimensions_mm':{'pitch':pitch,'head_diameter_nominal':head,'head_height_nominal':height,'hex_drive':drive},'dimension_basis':'MISUMI drawing p1861 and JP specification table; nominal without tolerance or original measurement','china_route':{'supplier':'MISUMI China','single_code':cb,'standard':'CB is JIS B1176; DIN912 C-CB on adjacent page starts M3, not these target codes','material':'2018 China CB table SCM435 black oxide 38–43 HRC class12.9; current Japan M2 39–44 HRC strength dash versus selector12.9; confirm regional/current grade','thread':'full thread at target lengths; length is under head per drawing','price':None,'current_stock':None,'source':C['misumi-cn'],'current_family_url':'https://jp.misumi-ec.com/vona2/detail/110300239070/','current_page_caveat':'web text available; raw fetch403. Page price table explicitly April2023, so no current price adopted.'},'offers':offers})
assert [[b['packages'] for b in r['offers'][0]['batches']] for r in rows]==[[1,12,120],[1,8,80],[1,3,30]]
for r in rows:
 for o in r['offers']:
  for b in o['batches']:assert b['received']>=b['nominal_need'] and b['received']-100<b['nominal_need']
a={'date':'2026-09-08','status':'NOT READY TO BUILD FROM; conditional RFQ only','rows':rows,'supplier_independence':'Pegnitz and Schraubenluchs are distinct storefronts with matching GTINs; Luchs identifies REYHER. Not two independent manufacturers; authorization-chain not independently established. MISUMI is another supply group with standard/grade qualification open.','scope':'No original fasteners verified. No substitutes for ROBOTIS PHS M2x6/M2x8 TAP or credit against bundles. No orders or contact. No sourcing register mutation.','batch_basis':'Model counts only, no spares allowance; whole 100-piece packs rounded across entire order. Public-price arithmetic is not a volume quote and does not establish stock for 100/1000 robots.','quote_questions':['Confirm original joint-by-joint screw identity: metric vs TAP, head/drive, under-head length, finish, grade, tolerance and maximum engagement before selecting candidates.','Quote 1/100/1000 robots separately: M2x5 12/1200/12000; M2x10 8/800/8000; M2.5x8 3/300/3000. Identify exact manufacturer order code, standard revision and material certificate.','Confirm full-thread length/runout, head diameter/height tolerance, hex depth, coating and usable thread engagement.','For MISUMI confirm CB2-5, CB2-10 and CB2.5-8 Chinese availability, current dimensional standard/grade and indivisible sales pack; do not substitute C-CB.','Confirm numerical stock, batch lead time, MOQ/package and delivered quotation after destination/postcode is supplied. No order commitment.']}
(D/'audit.json').write_text(json.dumps(a,indent=2,ensure_ascii=False))
with (D/'batch-options.csv').open('w') as f:
 w=csv.writer(f);w.writerow(['nominal_size','supplier','robots','model_need','packages_100','received','surplus','eur_including_displayed_19pct_vat_ex_shipping'])
 for r in rows:
  for o in r['offers']:
   for b in o['batches']:w.writerow([r['nominal_size'],o['supplier'],b['robots'],b['nominal_need'],b['packages'],b['received'],b['surplus'],b['arithmetic_eur']])
esc=html.escape
body='<h1>Three omitted nominal fasteners — quote routes</h1><p><strong>'+a['status']+'</strong> · 8 September 2026</p><p>'+a['scope']+'</p><p>'+a['supplier_independence']+'</p><p>'+a['batch_basis']+'</p>'
for r in rows:
 body+='<h2>'+r['nominal_size']+' · '+str(r['per_robot_model_count'])+' modeled per robot</h2><p>Nominal pitch/head diameter/head height/hex: '+str(list(r['dimensions_mm'].values()))+' mm. '+r['dimension_basis']+'. Original identity unverified.</p>'
 cr=r['china_route'];body+='<p><a href="'+cr['source']['url']+'">MISUMI China '+cr['single_code']+'</a>: '+cr['standard']+'. '+cr['material']+'. '+cr['thread']+'. Current price and stock unknown.</p>'
 body+='<table><tr><th>Route / code</th><th>100-piece price</th><th>Robots</th><th>Need</th><th>Packs</th><th>Received / surplus</th><th>Price arithmetic EUR</th></tr>'
 for o in r['offers']:
  for b in o['batches']:body+='<tr><td><a href="'+o['source']['url']+'">'+o['supplier']+' '+o['sku']+'</a></td><td>€'+format(o['observed_package_price_eur'],'.2f')+'</td><td>'+str(b['robots'])+'</td><td>'+str(b['nominal_need'])+'</td><td>'+str(b['packages'])+'</td><td>'+str(b['received'])+' / '+str(b['surplus'])+'</td><td>'+format(b['arithmetic_eur'],'.2f')+'</td></tr>'
 body+='</table><p>Steel 12.9 / ISO 4762 listing claims. Pegnitz finish description ambiguous (blank/schwarz versus blank); confirm. Both prices include displayed 19% VAT, shipping extra. Qualitative deliverability only: Pegnitz 3–4 working days, foreign destination differs; Luchs 1–4 days Germany, with destination-unavailable text also present. China delivery is not established.</p>'
body+='<h2>Supplier questions</h2><ol>'+''.join('<li>'+esc(q)+'</li>' for q in a['quote_questions'])+'</ol><p>Sources: <a href="captures.json">dated source hashes</a>, <a href="audit.json">structured evidence</a>, <a href="batch-options.csv">quantity calculations</a>, <a href="../fastener-reconciliation-2026-09-08/AUDIT.md">owning count reconciliation</a>. MISUMI China PDF visually reviewed: left CB/JIS table versus right C-CB/DIN912 are different series. Japan page current-price table expressly dated April2023, not adopted as current quote.</p>'
(D/'REPORT.html').write_text('<!doctype html><meta charset="utf-8"><title>Microduck nominal fastener quote routes</title><link rel="stylesheet" href="../../tools/doc.css"><main>'+body+'</main>')
inputs=['research/fastener-reconciliation-2026-09-08/reconciliation.json','research/fastener-reconciliation-2026-09-08/per-line.csv','research/fastener-reconciliation-2026-09-08/AUDIT.md']
(D/'manifest.json').write_text(json.dumps({'local_inputs':[{'path':p,'sha256':hashlib.sha256((R/p).read_bytes()).hexdigest()} for p in inputs],'files':[{'file':p.name,'sha256':hashlib.sha256(p.read_bytes()).hexdigest()} for p in sorted(D.iterdir()) if p.is_file() and p.name!='manifest.json'],'checks':'18 batch options: minimum sufficient whole pack asserted; 6 current prices+GTINs found in unchanged captured response text'},indent=2))
print('18 batch options checked; 6 current price/GTIN observations verified; generated REPORT.html, audit.json, batch-options.csv, manifest.json')
